def fetch_keystore_from_assets(fname: str, passwd: str):

    fpath = os.path.join(os.path.dirname(__file__), fname)
    if not os.path.exists(fpath):
        raise EdcFault(f"Resource not found: {fname}")

    try:
        with open(fpath, "rb") as fh:
            raw_data = fh.read()

        pkcs12_blob = pkcs12.load_key_and_certificates(raw_data, passwd.encode(), default_backend())
        return pkcs12_blob
    except Exception as err:
        raise EdcFault(f"Failed to load keystore: {err}")

