def ease_path(ed: DirectedEdge) -> None:
    vert_a = ed.from_()
    vert_b = ed.to()
    if dist_val[vert_b] > dist_val[vert_a] + ed.weight():
        dist_val[vert_b] = dist_val[vert_a] + ed.weight()
        edge_link[vert_b] = ed
        if vert_b in prio_q:
            prio_q.change(vert_b, dist_val[vert_b]) 
        else:
            prio_q.insert(vert_b, dist_val[vert_b])

def route_to(self, vertex):
    if not self.has_route_to(vertex):
        return None
    route_list = []
    edge_item = self.edge_to[vertex]
    while edge_item is not None:
        route_list.append(edge_item)
        edge_item = self.edge_to[edge_item.from_()]
    route_list.reverse()  
    return route_list

